/*
 * Meta data for each texture in Maps textures
 */
#include "assets/map_textures.h"

typedef struct MapTexMeta {
    const char* name;          /* e.g. "gv__atif" */
    const char* otrPath;       /* __OTR__textures/gv__tex/gv__atif */
    const char* auxOtrPath;    /* aux raster path, or NULL when the texture has no aux tile */
    u16 mainW, mainH;
    u8  mainFmt, mainDepth;    /* G_IM_FMT_*, G_IM_SIZ_* */
    u8  mainWrapW, mainWrapH;  /* G_TX_* */
    u8  filter;                /* 0 / 2 */
    u8  auxCombineType;        /* TextureHeader bitfield, already unpacked */
    u8  auxCombineSubType;     /* TextureHeader bitfield, already unpacked */
    u8  extraTiles;            /* EXTRA_TILE_* */
    u8  isVariant;
    u16 auxW, auxH;
    u8  auxFmt, auxDepth, auxWrapW, auxWrapH;
    u8  hasMipmaps;
} MapTexMeta;

typedef struct MapTexArchive {
    const char* archive; /* e.g. "gv__tex" */
    const MapTexMeta* textures;
    u32 count;
} MapTexArchive;

